using FluentValidation;using MediatR;using RevenuUsage.Domain.Entities;using RevenuUsage.Domain.Interfaces;namespace RevenuUsage.Application.Features.Reporting;public record GetDashboardQuery(DateTime AsOfDate):IRequest<DashboardSummary>;public record GetForeignReserveReportQuery(DateTime StartDate,DateTime EndDate):IRequest<IReadOnlyList<ForeignReserveReportRow>>;public record GetObligationReportQuery(DateTime? StartDate,DateTime? EndDate,string? Status):IRequest<IReadOnlyList<ObligationReportRow>>;public sealed class ReportingHandler:IRequestHandler<GetDashboardQuery,DashboardSummary>,IRequestHandler<GetForeignReserveReportQuery,IReadOnlyList<ForeignReserveReportRow>>,IRequestHandler<GetObligationReportQuery,IReadOnlyList<ObligationReportRow>>{private readonly IReportingRepository _r;public ReportingHandler(IReportingRepository r)=>_r=r;public Task<DashboardSummary>Handle(GetDashboardQuery q,CancellationToken ct)=>_r.GetDashboardAsync(q.AsOfDate,ct);public async Task<IReadOnlyList<ForeignReserveReportRow>>Handle(GetForeignReserveReportQuery q,CancellationToken ct)=>(await _r.GetForeignReserveAsync(q.StartDate,q.EndDate,ct)).ToList();public async Task<IReadOnlyList<ObligationReportRow>>Handle(GetObligationReportQuery q,CancellationToken ct)=>(await _r.GetObligationsAsync(q.StartDate,q.EndDate,q.Status,ct)).ToList();}public sealed class ForeignReserveReportValidator:AbstractValidator<GetForeignReserveReportQuery>{public ForeignReserveReportValidator(){RuleFor(x=>x.EndDate).GreaterThanOrEqualTo(x=>x.StartDate);}}public sealed class ObligationReportValidator:AbstractValidator<GetObligationReportQuery>{public ObligationReportValidator(){RuleFor(x=>x.EndDate).GreaterThanOrEqualTo(x=>x.StartDate!.Value).When(x=>x.StartDate.HasValue&&x.EndDate.HasValue);RuleFor(x=>x.Status).Must(s=>s is null or "Open" or "Paid" or "Overdue");}}
